Apply this change to `src/Store.ts`: Apply initial state (concact) if provided so that even if no actions sent yet, the initial state is provided to subscribers.

Reply with the complete updated file in one code block and nothing else.

```typescript
import { Flow } from './Flow';
import { Soak, completeSoak } from './Soak';
import { Observable, Subject } from 'rxjs';

/**
 * The dispatch and state that comprises a dw Store.
 */
export type Store<State, Action> = {
    dispatch$: Subject<Action>;
    state$: Observable<State>;
};

/**
 * Links a flow, soak and initial state to create a store object.
 * Objects passed to the dispatch function will be filtered through the flow
 * then scanned to apply state changes defined by the soak, starting with the initial state.
 * 
 * @param flow the transformations to the action stream
 * @param soak the transformations to state based on actions
 * @param initialState  the initial state prior to any applied soaks.
 */
export const createStore = <State, Action>(
    flow: Flow<Action>,
    soak: Soak<State, Action>,
    initialState?: State
): Store<State, Action> => {
    const subject$ = new Subject<Action>();
    const fullSoak = completeSoak(soak);
    return {
        dispatch$: subject$,
        state$: flow(subject$).scan<Action, State>(fullSoak, initialState).share()
    };
};

export default createStore;```

```typescript
import { Flow } from './Flow';
import { Soak, completeSoak } from './Soak';
import { Observable, Subject, of } from 'rxjs';
import { concat, scan } from 'rxjs/operators';

/**
 * The dispatch and state that comprises a dw Store.
 */
export type Store<State, Action> = {
    dispatch$: Subject<Action>;
    state$: Observable<State>;
};

/**
 * Links a flow, soak and initial state to create a store object.
 * Objects passed to the dispatch function will be filtered through the flow
 * then scanned to apply state changes defined by the soak, starting with the initial state.
 * 
 * @param flow the transformations to the action stream
 * @param soak the transformations to state based on actions
 * @param initialState  the initial state prior to any applied soaks.
 */
export const createStore = <State, Action>(
    flow: Flow<Action>,
    soak: Soak<State, Action>,
    initialState?: State
): Store<State, Action> => {
    const subject$ = new Subject<Action>();
    const fullSoak = completeSoak(soak);

    let state$: Observable<State>;

    if (initialState !== undefined) {
        // If initial state is provided, emit it first, then apply actions
        state$ = concat(
            of(initialState),
            flow(subject$).pipe(scan(fullSoak))
        );
    } else {
        // If no initial state, just scan the actions (will start with undefined or throw if not handled)
        state$ = flow(subject$).pipe(scan(fullSoak));
    }

    return {
        dispatch$: subject$,
        state$: state$.share()
    };
};

export default createStore;
```

