import {Document} from 'idai-components-2';
import {DocumentDatastore} from '../../datastore/document-datastore';


export async function importCatalog(documents: Array<Document>,
                                    datastore: DocumentDatastore,
                                    username: string): Promise<{ errors: string[][], successfulImports: number }> {

    const errors: string[][] = [];
    let successfulImports = 0;

    for (const doc of documents) {
        try {
            // Preliminary implementation: attempt to save the document
            // In a real scenario, you might want to validate the document structure first
            await datastore.save(doc);
            successfulImports++;
        } catch (error) {
            console.error('Failed to import document:', doc.id, error);
            errors.push([doc.id, `Import failed: ${error instanceof Error ? error.message : String(error)}`]);
        }
    }

    return { errors, successfulImports };
}
