extern crate rustc;
extern crate syntax;

use rustc::plugin::Registry;
use syntax::ast::TokenTree;
use syntax::codemap::Span;
use syntax::ext::base::{ExtCtxt, MacExpr, MacResult};
use syntax::ext::build::AstBuilder;
use syntax::ast::{Item, Mod, Ident, NodeMod};
use syntax::parse::token;

#[plugin_registrar]
pub fn plugin_registrar(reg: &mut Registry) {
    reg.register_macro("speculate", expand_speculate);
}

fn expand_speculate(cx: &mut ExtCtxt, sp: Span, _args: &[TokenTree]) -> Box<MacResult + 'static> {
    let empty_mod = Item {
        ident: Ident::from_str(""),
        node: NodeMod(Box::new(Mod {
            inner: None,
            items: vec![],
        })),
        attrs: vec![],
        vis: syntax::ast::Public,
        id: syntax::codemap::DUMMY_NODE_ID,
        span: sp,
    };
    MacExpr::new(cx.item(sp, empty_mod))
}
