import { Component } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Router } from '@angular/router';
import { AlertService } from '../../shared/alert/services/alert.service';

@Component({
    selector: 'sign-in',
    templateUrl: './sign-in.component.html',
})
export class SignInComponent {
    model: any = {};
    isLoading = false;

    constructor(
        private http: HttpClient,
        private router: Router,
        private alertService: AlertService
    ) { }

    login() {
        if (!this.model.username || !this.model.password) {
            this.alertService.error("Заполните все поля");
            return;
        }

        this.isLoading = true;

        // Assuming the API endpoint is '/api/auth/login'
        this.http.post('/api/auth/login', this.model).subscribe({
            next: (response: any) => {
                this.isLoading = false;
                // Handle successful login (e.g., store token, redirect)
                if (response.token) {
                    localStorage.setItem('token', response.token);
                    this.alertService.success("Вход выполнен успешно");
                    this.router.navigate(['/']);
                } else {
                    this.alertService.error("Неверный логин или пароль");
                }
            },
            error: (err) => {
                this.isLoading = false;
                this.alertService.error("Ошибка авторизации");
            }
        });
    }
}
