import { ReturnStatement, VariableStatement, VariableDeclaration, ModifierFlags } from 'typescript';
import { Context } from '../contexts';
import { EmitResult, emit } from './';

export const emitReturnStatement = ({ expression }: ReturnStatement, context: Context): EmitResult => {
  const emit_result = emit(expression, context);
  return {
    ...emit_result,
    emitted_string: `return ${emit_result.emitted_string};`
  };
};

export const emitVariableStatement = (statement: VariableStatement, context: Context): EmitResult => {
  const declarations = statement.declarationList.declarations;
  const modifiers = statement.declarationList.modifiers;

  let kind = 'var';
  if (modifiers) {
    if (modifiers.some(m => m.kind === 126 /* ModifierFlags.Let */)) {
      kind = 'let';
    } else if (modifiers.some(m => m.kind === 128 /* ModifierFlags.Const */)) {
      kind = 'const';
    }
  }

  const parts: string[] = [];

  for (const declaration of declarations) {
    let name = '';
    if (declaration.name.kind === 253 /* SyntaxKind.Identifier */) {
      name = declaration.name.text;
    } else if (declaration.name.kind === 254 /* SyntaxKind.ArrayBindingPattern */) {
      // Simplified handling for array destructuring if needed, otherwise fallback
      // For basic implementation, we might skip complex destructuring or handle simply
      // Here we assume simple identifier for now or could implement binding pattern emit
      // To keep it robust, let's assume simple identifier for this basic change
      // If destructuring is needed, a separate emitBindingPattern function would be required
      name = '__temp_var'; // Placeholder for destructuring if not implemented
    }

    let init = '';
    if (declaration.initializer) {
      const init_result = emit(declaration.initializer, context);
      init = ` = ${init_result.emitted_string}`;
    }

    parts.push(`${kind} ${name}${init}`);
  }

  return {
    ...context,
    emitted_string: parts.join(', ') + ';'
  };
};
