    static ref IDT: idt::Idt = {
        let mut idt = idt::Idt::new();

        idt.set_handler(0, divide_by_zero_wrapper);

        idt
    };
}

pub fn init() {
    IDT.load();
}

#[derive(Debug)]
#[repr(C)]
struct ExceptionStackFrame {
    instruction_pointer: u64,
    code_segment: u64,
    cpu_flags: u64,
    stack_pointer: u64,
    stack_segment: u64,
}

use vga_buffer::print_error;

macro_rules! define_exception_handler {
    ($name:ident, $num:expr) => {
        #[naked]
        extern "C" fn $name() -> ! {
            unsafe {
                asm!("mov rdi, rsp
                      sub rsp, 8 // align the stack pointer
                      call $0"
                      :: "i"($name ## _handler as extern "C" fn(_) -> !)
                      : "rdi" : "intel");
                ::core::intrinsics::unreachable();
            }
        }

        extern "C" fn $name ## _handler(stack_frame: *const ExceptionStackFrame)
            -> !
        {
            unsafe {
                print_error(format_args!("EXCEPTION: {}\n{:#?}", stringify!($name),
                    *stack_frame));
            }
            loop {}
        }
    };
}

define_exception_handler!(divide_by_zero, 0);
