```typescript
import { ADDON_STATE_CHANGED, ADDON_STATE_SET } from '@storybook/core-events';

import {
  HooksContext,
  applyHooks,
  useMemo,
  useCallback,
  useRef,
  useState,
  useReducer,
  useEffect,
  useChannel,
  useStoryContext,
  useParameter,
} from '@storybook/addons';

export {
  HooksContext,
  applyHooks,
  useMemo,
  useCallback,
  useRef,
  useState,
  useReducer,
  useEffect,
  useChannel,
  useStoryContext,
  useParameter,
};

// Cache for HMR compatibility to preserve state across module reloads
const addonStateCache: Record<string, any> = {};

export function useAddonState<S>(addonId: string, defaultState?: S): [S, (s: S) => void] {
  // Initialize state from cache if available, otherwise use defaultState
  const [state, setState] = useState<S>(() => {
    if (addonStateCache[addonId] !== undefined) {
      return addonStateCache[addonId];
    }
    return defaultState;
  });

  // Memoize the event handlers object to prevent unnecessary re-renders and HMR issues
  const eventHandlers = useMemo(() => ({
    [`${ADDON_STATE_CHANGED}-manager-${addonId}`]: (s: S) => {
      setState(s);
      addonStateCache[addonId] = s;
    },
    [`${ADDON_STATE_SET}-manager-${addonId}`]: (s: S) => {
      setState(s);
      addonStateCache[addonId] = s;
    },
  }), [addonId]);

  const emit = useChannel(eventHandlers, [addonId]);

  useEffect(() => {
    // init
    if (defaultState !== undefined) {
      emit(`${ADDON_STATE_SET}-client-${addonId}`, defaultState);
    }
  }, []);

  return [
    state,
    s => {
      setState(s);
      addonStateCache[addonId] = s;
      emit(`${ADDON_STATE_CHANGED}-client-${addonId}`, s);
    },
  ];
