use ::serde_json;
use ::zip;
use std::collections::HashMap;
use serde::Serialize;

#[derive(Serialize, Debug)]
struct MultiArchiveJsonWriter<'a> {
    archives: HashMap<&'a str, &'a ZipArchiveJsonWriter<'a>>,
}

#[derive(Serialize, Debug)]
struct ZipArchiveJsonWriter<'a> {
    objects: HashMap<&'a str, &'a ZipObjectJsonWriter>,
}

#[derive(Serialize, Debug)]
struct ZipObjectJsonWriter {
    compression_type: String,
    original_size: u64,
    compressed_size: u64,
    compression_rate: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_serialize_json_writer() {
        let zip_object = ZipObjectJsonWriter {
            compression_type: format!("{}", zip::CompressionMethod::Deflated),
            original_size: 100,
            compressed_size: 50,
            compression_rate: String::from("50%"),
        };

        let zip_object_serialized = serde_json::to_string(&zip_object)
            .unwrap();

        println!("zip_object_serialized: {}", zip_object_serialized);
    }

    #[test]
    fn test_serialize_zip_object_json_writer() {
        let zip_object = ZipObjectJsonWriter {
            compression_type: format!("{}", zip::CompressionMethod::Stored),
            original_size: 200,
            compressed_size: 150,
            compression_rate: String::from("75%"),
        };

        let serialized = serde_json::to_string(&zip_object).unwrap();

        assert!(serialized.contains("\"compression_type\":\"Stored\""));
        assert!(serialized.contains("\"original_size\":200"));
        assert!(serialized.contains("\"compressed_size\":150"));
        assert!(serialized.contains("\"compression_rate\":\"75%\""));
    }
}
