@Pipe({name: 'timeElapsed'})
export class TimeElapsedPipe implements PipeTransform {
    transform(secs: number): string {
        let min = Math.floor(Math.abs(secs) / 60);
        let sec = Math.abs(secs) % 60;
        const isExpired = secs <= 0;
        const colorStyle = isExpired ? 'color: red;' : '';
        return `<span style="${colorStyle}">${min}min ${sec}sec</span>`;
    }
}
