```typescript
import {Directive, ElementRef, Input, OnInit, Renderer2} from '@angular/core';
declare var google: any;
declare var googleLoaded: any;

@Directive({
  selector: '[GoogleChart]',
})
export class GoogleChart implements OnInit {
  public _element: any;
  @Input('chartType') public chartType: string;
  @Input('chartOptions') public chartOptions: Object;
  @Input('chartData') public chartData: Object;

  constructor(public element: ElementRef, private renderer: Renderer2) {
    this._element = this.element.nativeElement;
  }

  ngOnInit() {
    if (!googleLoaded) {
      googleLoaded = true;
      google.charts.load('current', {'packages': ['corechart', 'gauge']});
    }
    setTimeout(() => this.drawGraph(this.chartOptions, this.chartType, this.chartData, this._element), 1000);
  }

  drawGraph(chartOptions, chartType, chartData, ele) {
    google.charts.setOnLoadCallback(drawChart);

    function drawChart() {
      var wrapper;
      // Ensure the element has an ID for the containerId if not already present
      if (!ele.id) {
        const id = 'google-chart-' + Math.random().toString(36).substr(2, 9);
        ele.id = id;
      }

      wrapper = new google.visualization.ChartWrapper({
        chartType: chartType,
        dataTable: chartData,
        options: chartOptions || {},
        containerId: ele.id
      });
      wrapper.draw();
    }
  }
}
