    private static instance: RouterProvider = null;

    public readonly ROUTING: string = '/config/Routing';
    protected moduleProvider: ModuleProvider;
    protected routers: IRouter[] = [];

    private constructor() {
        this.moduleProvider = ModuleProvider.getInstance();
    }

