//! Useful callbacks used by ethernet's specific filter

/// Callbacks for Ethernet packet processing
pub struct EthernetCallbacks {
    /// Callback function for handling received packets
    pub on_receive: Option<Box<dyn FnMut(&[u8]) + Send>>,
    /// Callback function for handling transmitted packets
    pub on_transmit: Option<Box<dyn FnMut(&[u8]) + Send>>,
}

impl EthernetCallbacks {
    /// Create a new empty EthernetCallbacks instance
    pub fn new() -> Self {
        EthernetCallbacks {
            on_receive: None,
            on_transmit: None,
        }
    }

    /// Set the receive callback
    pub fn set_on_receive<F>(&mut self, callback: F)
    where
        F: FnMut(&[u8]) + Send + 'static,
    {
        self.on_receive = Some(Box::new(callback));
    }

    /// Set the transmit callback
    pub fn set_on_transmit<F>(&mut self, callback: F)
    where
        F: FnMut(&[u8]) + Send + 'static,
    {
        self.on_transmit = Some(Box::new(callback));
    }
}

impl Default for EthernetCallbacks {
    fn default() -> Self {
        Self::new()
    }
}
