/// A platform-specific event abstraction.
///
/// This trait represents a single event that can be waited on by a [`Selector`].
/// The specific requirements and semantics depend on the underlying platform:
///
/// - **Unix**: Typically wraps a file descriptor that is registered with an epoll/kqueue instance.
/// - **Windows**: Typically wraps an I/O completion port or overlapped I/O operation.
///
/// Implementations must ensure that the event is properly associated with a selector
/// and can be efficiently retrieved when the event occurs.
pub trait Event: std::fmt::Debug + Send {
    /// Returns the underlying handle or identifier for this event.
    fn as_raw(&self) -> std::os::raw::c_int;
}

/// A platform-specific system event abstraction.
///
/// This trait represents a system-level event, such as a signal or a special
/// notification, that can be waited on by a [`Selector`].
///
/// The specific requirements depend on the underlying platform:
///
/// - **Unix**: May represent signals, pipes, or other file descriptors.
/// - **Windows**: May represent overlapped I/O operations or other kernel objects.
///
/// Implementations must ensure that the event is properly associated with a selector
/// and can be efficiently retrieved when the event occurs.
pub trait SysEvent: std::fmt::Debug + Send {
    /// Returns the underlying handle or identifier for this system event.
    fn as_raw(&self) -> std::os::raw::c_int;
}

#[cfg(unix)]
pub use self::unix::{
    pipe, set_nonblock, Event, EventedFd, Events, Io, Selector, SysEvent, TcpListener, TcpStream,
    UdpSocket, Waker,
};

#[cfg(unix)]
pub mod unix;

#[cfg(windows)]
pub use self::windows::{
    Binding, Event, Events, Overlapped, Selector, SysEvent, TcpListener, TcpStream, UdpSocket,
    Waker,
};

#[cfg(windows)]
mod windows;
