```typescript
'use strict';

import fs = require('fs');
import path = require('path');

var binPathCache: { [bin: string]: string; } = {}

export function getBinPath(binname: string) {
	binname = correctBinname(binname);

	if (binPathCache[binname]) return binPathCache[binname];

    // clang-format.executable has a valid absolute path
    if (fs.existsSync(binname)) {
        binPathCache[binname] = binname;
        return binname;
    }

	if (process.env["PATH"]) {
		var pathparts = process.env["PATH"].split(path.delimiter);
		for (var i = 0; i < pathparts.length; i++) {
			let binpath = path.join(pathparts[i], binname);
			if (fs.existsSync(binpath)) {
				binPathCache[binname] = binpath;
				return binpath;
			}
		}
	}

	// On Windows, also check the current working directory and system directories
	// if not found in PATH. This helps with executables installed in common
	// locations that might not be in PATH but are accessible via standard
	// Windows search paths (like System32, Windows, etc.) or relative to the
	// extension's location.
	if (process.platform === 'win32') {
		// Check relative to the current working directory
		let cwdBinpath = path.join(process.cwd(), binname);
		if (fs.existsSync(cwdBinpath)) {
			binPathCache[binname] = cwdBinpath;
			return cwdBinpath;
		}

		// Check relative to the extension's root directory (common for bundled tools)
		// Assuming this file is in src/, the root is likely one level up or we can
		// try common subdirectories like 'bin' or 'tools'.
		// A robust approach often involves checking a 'bin' directory relative to
		// the extension root if known, but without that context, we stick to standard
		// PATH and CWD. However, a common improvement for Windows is to ensure
		// we check for the .exe extension properly if it wasn't added by correctBinname
		// (though correctBinname handles it).

		// Another common issue on Windows is that some tools might be in
		// %LOCALAPPDATA%\Programs or similar. Without specific config, we can't
		// guess these. But we can ensure we check the standard Windows directories
		// if they are not in PATH (though they usually are).

		// Let's add a check for common local installation paths if the binary
		// is not found in PATH. This is a heuristic improvement.
		const localAppData = process.env['LOCALAPPDATA'];
		if (localAppData) {
			const commonPaths = [
				path.join(localAppData, 'Programs', 'clang-tools'),
				path.join(localAppData, 'LLVM'),
				path.join(localAppData, 'Microsoft', 'WindowsApps')
			];
			for (const commonPath of commonPaths) {
				const candidate = path.join(commonPath, binname);
				if (fs.existsSync(candidate)) {
					binPathCache[binname] = candidate;
					return candidate;
				}
			}
		}
	}

	// Else return the binary name directly (this will likely always fail downstream) 
	binPathCache[binname] = binname;
	return binname;
}

function correctBinname(binname: string) {
	if (process.platform === 'win32') {
        if(binname.substr(binname.length - 4).toLowerCase() !== '.exe') {
