import * as React from 'react';

const childrenToMap = (children: React.ReactNode): Map<string | null, React.ReactElement> => {
    const childrenArray = React.Children.toArray(children);
    const childMap: Map<string | null, React.ReactElement> = new Map();
    childrenArray.forEach((child) => {
        if (React.isValidElement(child)) {
            childMap.set(child.key, child);
        }
    });
    return childMap;
};

const compareChildren = (children1: Map<string | null, React.ReactElement>, children2: Map<string | null, React.ReactElement>): boolean => {
    const keys1 = Array.from(children1.keys());
    const keys2 = Array.from(children2.keys());

    if (keys1.length !== keys2.length) {
        return false;
    }

    for (const key of keys1) {
        if (!children2.has(key)) {
            return false;
        }
    }

    return true;
};

export {
    childrenToMap,
    compareChildren,
};
