#![allow(dead_code)]

#[macro_use]
extern crate pest;

extern crate rand;

mod parse;

use pest::*;
use parse::*;

#[derive(Debug)]
pub struct Roller<'a> {
    roll: &'a str,
    total: i32,
}

impl<'a> Roller<'a> {
    fn new(roll: &str) -> Roller {
        let mut parser = Rdp::new(StringInput::new(roll));
        parser.expression();

        Roller {
            roll: roll,
            total: parser.compute(),
        }
    }

    fn reroll(&mut self) -> i32 {
        let mut parser = Rdp::new(StringInput::new(self.roll));
        parser.expression();

        self.total = parser.compute();

        self.total
    }

    fn total(&self) -> i32 {
        self.total
    }

    pub fn roll_dice(roll: &str) -> i32 {
        let mut parser = Rdp::new(StringInput::new(roll));
        parser.expression();
        parser.compute()
    }
}

#[test]
fn it_works() {
    let mut roller = Roller::new("4d6");

    assert!((4 <= roller.total()) && (roller.total() <= 24));

    assert!(roller.total() != roller.reroll());
}
