```typescript
export default {
  name: 'FeathersVuexInputWrapper',
  props: {
    item: {
      type: Object,
      required: true
    },
    prop: {
      type: String,
      required: true
    }
  },
  data: () => ({
    clone: null,
    debounceTimer: null
  }),
  computed: {
    current() {
      return this.clone || this.item
    }
  },
  methods: {
    createClone(e) {
      this.clone = this.item.clone()
    },
    cleanup() {
      this.$nextTick(() => {
        this.clone = null
      })
    },
    handler(e, callback) {
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer)
      }

      this.debounceTimer = setTimeout(() => {
        if (!this.clone) {
          this.createClone()
        }
        const maybePromise = callback({
          event: e,
          clone: this.clone,
          prop: this.prop,
          data: { [this.prop]: this.clone[this.prop] }
        })
        if (maybePromise && maybePromise.then) {
          maybePromise.then(this.cleanup)
        } else {
          this.cleanup()
        }
        this.debounceTimer = null
      }, 300)
    }
  },
  render() {
    const { current, prop, createClone, handler } = this
    return this.$scopedSlots.default({ current, prop, createClone, handler })
  }
}
