```rust
use at::{AtRust, AtTrigger};
use plugins::get;

use select::document::Document;
use select::predicate::{Attr, Class, Name};
use rand;

pub fn eksi(trigger: &AtTrigger, at: &AtRust) {
    let url = format!("https://eksisozluk.com/{}", trigger.command_message);
    let body = get(&url);

    let body_str = body.unwrap();
    let document = Document::from_str(&body_str);

    let entries: Vec<String> = document
        .find(Attr("id", "entry-list"))
        .find(Name("li"))
        .filter_map(|entry| {
            entry
                .find(Class("content"))
                .first()
                .map(|el| el.text().to_string())
        })
        .collect();

    if entries.is_empty() {
        return;
    }

    let random_index = rand::random::<usize>() % entries.len();
    at.reply(trigger, &entries[random_index]);
}
```

