const addition = (a: number, b: number): number => a + b;

const subtraction = (a: number, b: number): number => a - b;

const multiplication = (a: number, b: number): number => a * b;

export const sum = (array: number[]): number => {
  return array.reduce(addition, 0);
};

export const sumAndDiff = (array: number[]): number => {
  return array.reduce((prev, curr, index) => {
    if (index % 2 === 0) {
      return addition(prev, curr);
    } else {
      return subtraction(prev, curr);
    }
  }, 0);
};

export const product = (array: number[]): number => {
  return array.reduce(multiplication, 1);
};
