```typescript
import React, { Component, RefObject, createRef } from 'react';
import window from 'global';

interface IFrameProps {
  id: string;
  key?: string;
  title: string;
  src: string;
  allowFullScreen: boolean;
  scale: number;
  style?: any;
}

interface BodyStyle {
  width: string;
  height: string;
  transform: string;
  transformOrigin: string;
}

export class IFrame extends Component<IFrameProps> {
  iframeRef: RefObject<HTMLIFrameElement> = createRef();

  componentDidMount() {
    // The iframe element is available via ref in React 16.3+
    // We don't strictly need to query by ID if we have the ref, 
    // but we ensure the ref is attached.
  }

  shouldComponentUpdate(nextProps: IFrameProps) {
    const { scale } = nextProps;
    // eslint-disable-next-line react/destructuring-assignment
    if (scale !== this.props.scale) {
      this.setIframeBodyStyle({
        width: `${scale * 100}%`,
        height: `${scale * 100}%`,
        transform: `scale(${1 / scale})`,
        transformOrigin: 'top left',
      });
    }
    return false;
  }

  setIframeBodyStyle(style: BodyStyle) {
    if (this.iframeRef.current) {
      const doc = this.iframeRef.current.contentDocument;
      if (doc && doc.body) {
        Object.assign(doc.body.style, style);
      }
    }
  }

  render() {
    const { id, title, src, allowFullScreen, scale, ...rest } = this.props;
    return <iframe ref={this.iframeRef} id={id} title={title} src={src} allowFullScreen={allowFullScreen} {...rest} loading="lazy"/>;
  }
}
