'use strict';
import * as vscode from 'vscode';
import * as path from 'path';
import * as fs from 'fs';

export function activate(context: vscode.ExtensionContext) {
    console.log('Dart-Code activated!');
    detectAndAlertSDK();
}

export function deactivate() {
    console.log('Dart-Code deactivated!');
}

function detectAndAlertSDK() {
    const sdkPath = process.env.DART_SDK;
    if (!sdkPath) {
        vscode.window.showErrorMessage(
            'Dart SDK not found. Please ensure the DART_SDK environment variable is set or the SDK is installed in a standard location.'
        );
        return;
    }

    const dartExecutable = path.join(sdkPath, 'bin', 'dart');
    if (!fs.existsSync(dartExecutable)) {
        vscode.window.showErrorMessage(
            `Dart SDK executable not found at ${dartExecutable}. Please check your DART_SDK environment variable.`
        );
    }
}
