    fn call<S>(&self) -> Vec<S>
    where
      S: Into<String>,
    {
        vec!("new-window", "-t", &self.window_name, "-d", "-c", &self.root_path.to_str().unwrap(), &self.session_name)
    }
}

pub struct Split {
    pub session_name: String,
    pub window_name: String,
    pub root_path: Path,
    pub direction: String
}

