    where
      S: Into<String>,
    {
        let split_cmd = if self.direction == "v" { "split-window" } else { "split-window -h" };
        vec![split_cmd, "-t", &format!("{}:{}", &self.session_name, &self.window_name), "-d", "-c", &self.root_path.to_str().unwrap()]
    }
