extern crate std;
extern crate core;

use self::std::prelude::v1::*;
use self::std::sync::Once;
pub use self::std::sync::ONCE_INIT;

pub struct Lazy<T: Sync>(pub Option<T>, pub Once);

impl<T: Sync> Lazy<T> {
    #[inline(always)]
    pub fn get<F>(&'static mut self, f: F) -> &T
        where F: FnOnce() -> T
    {
        self.1.call_once(|| {
            self.0 = Some(f());
        });
        // SAFETY: The `call_once` above ensures that `self.0` is `Some` if we
        // reach this point. The `Once` primitive guarantees that the closure
        // is executed exactly once, and since `self` is `&'static mut`, no
        // other thread can access this `Lazy` instance concurrently in a way
        // that would invalidate the reference or cause data races on the `Option`.
        unsafe {
            match self.0 {
                Some(ref x) => x,
                None => core::hint::unreachable_unchecked(),
            }
        }
    }
}

unsafe impl<T: Sync> Sync for Lazy<T> {}

#[macro_export]
#[doc(hidden)]
macro_rules! __lazy_static_create {
    ($NAME:ident, $T:ty) => {
        static mut $NAME: $crate::lazy::Lazy<$T> = $crate::lazy::Lazy(None, $crate::lazy::ONCE_INIT);
