use std::fmt;

/// Represents a value that may or may not be present.
pub trait Maybe<T> {
    type Head;
    type Tail;

    fn is_present(&self) -> bool;
    fn head(&self) -> Option<&Self::Head>;
    fn tail(&self) -> Option<&Self::Tail>;
}

/// A value that is definitely present.
pub struct Present<T> {
    pub value: T,
}

impl<T> Present<T> {
    pub fn new(value: T) -> Self {
        Present { value }
    }
}

impl<T: fmt::Debug> fmt::Debug for Present<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Present({:?})", self.value)
    }
}

/// A value that is definitely absent.
pub struct Absent<T> {
    _marker: std::marker::PhantomData<T>,
}

impl<T> Absent<T> {
    pub fn new() -> Self {
        Absent {
            _marker: std::marker::PhantomData,
        }
    }
}

impl<T: fmt::Debug> fmt::Debug for Absent<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Absent")
    }
}

/// A recursive list-like structure where each element can be present or absent.
/// In the recursive case, `Head` represents the current element type,
/// and `Tail` represents the rest of the structure.
pub enum MaybeList<T> {
    Present(Present<T>),
    Absent(Absent<T>),
    Recursive(Box<MaybeList<T>>),
}

impl<T> MaybeList<T> {
    pub fn present(value: T) -> Self {
        MaybeList::Present(Present::new(value))
    }

    pub fn absent() -> Self {
        MaybeList::Absent(Absent::new())
    }

    pub fn recursive(inner: MaybeList<T>) -> Self {
        MaybeList::Recursive(Box::new(inner))
    }
}

impl<T: fmt::Debug> fmt::Debug for MaybeList<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            MaybeList::Present(p) => write!(f, "Present({:?})", p.value),
            MaybeList::Absent(a) => write!(f, "Absent"),
            MaybeList::Recursive(r) => write!(f, "Recursive({:?})", r),
        }
    }
}

impl<T> Maybe<T> for MaybeList<T> {
    type Head = T;
    type Tail = MaybeList<T>;

    fn is_present(&self) -> bool {
        match self {
            MaybeList::Present(_) => true,
            MaybeList::Absent(_) => false,
            MaybeList::Recursive(inner) => inner.is_present(),
        }
    }

    fn head(&self) -> Option<&Self::Head> {
        match self {
            MaybeList::Present(p) => Some(&p.value),
            MaybeList::Absent(_) => None,
            MaybeList::Recursive(inner) => inner.head(),
        }
    }

    fn tail(&self) -> Option<&Self::Tail> {
        match self {
            MaybeList::Present(_) => None,
            MaybeList::Absent(_) => None,
            MaybeList::Recursive(inner) => Some(inner.as_ref()),
        }
    }
}

#[test]
fn it_works() {
    let present_list = MaybeList::present(42);
    assert!(present_list.is_present());
    assert_eq!(present_list.head(), Some(&42));
    assert_eq!(present_list.tail(), None);

    let absent_list = MaybeList::absent();
    assert!(!absent_list.is_present());
    assert_eq!(absent_list.head(), None);
    assert_eq!(absent_list.tail(), None);

    let recursive_list = MaybeList::recursive(MaybeList::present(42));
    assert!(recursive_list.is_present());
    assert_eq!(recursive_list.head(), Some(&42));
    assert!(recursive_list.tail().is_some());
}
