    for (var service in config["services"]) {
        monitoredSocks.push(
            new MonitoredSocket(service.endpoint, service.port)
        );
    }
}

function processResponse(): string {
    var output: string = "";
    for (var i = 0; i < monitoredSocks.length; i++) {
        var sock = monitoredSocks[i];
        sock.connect();
        output += sock.isUp ? "UP" : "DOWN";
    }

    return output;
}

