import * as React from 'react';
import * as ReactDOM from 'react-dom';
import * as NotificationSystem from 'react-notification-system';

interface NGReactComponentProps {
    message: string;
}

interface NGReactComponentState {
}

class NGReactComponent extends React.Component<NGReactComponentProps, NGReactComponentState> {
    private _notificationSystem: any;

    constructor(props: NGReactComponentProps) {
        super(props);
    }

    _addNotification(event: React.SyntheticEvent) {
        event.preventDefault();
        this._notificationSystem.addNotification({
            message: this.props.message,
            level: 'success'
        });
    }

    componentDidMount() {
        this._notificationSystem = this.refs.notificationSystem;
    }

    render() {
        return (
            <div>
                <p>Say Hello From React!</p>
                <p>
                    <button onClick={this._addNotification.bind(this)}>Hello</button>
                </p>
                <NotificationSystem ref="notificationSystem" />
            </div>
        );
    }
}

export class NGReact {

    static initialize(message: string) {
        ReactDOM.render(<NGReactComponent message={message} />, document.getElementById('ng-react-component'));
    }

}
