```typescript
import * as React from 'react';
import './App.css';

import logo from './logo.svg';

class App extends React.Component<{}, { apiMessage: string, error: string | null }> {
  constructor(props: object) {
    super(props);

    this.state = { apiMessage: "", error: null };
  }

  public componentDidMount() {
    fetch("/api")
      .then(response => {
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        return response.text();
      })
      .then(apiMessage => {
        this.setState({ apiMessage, error: null });
      })
      .catch(error => {
        this.setState({ apiMessage: "", error: error.message });
      });
  }

  public render() {
    return (
      <div className="App">
        <header className="App-header">
          <img src={logo} className="App-logo" alt="logo" />
          <h1 className="App-title">Welcome to React</h1>
        </header>
        <p className="App-intro">
          To get started, edit <code>src/App.tsx</code> and save to reload.
        </p>
        {this.state.error ? (
          <p style={{ color: 'red' }}>Error: {this.state.error}</p>
        ) : (
          <p>{this.state.apiMessage}</p>
        )}
      </div>
    );
  }
}

export default App;
