use std::collections::hash_map::HashMap;
use js_types::js_type::{JsType, JsT};

pub type JsProto = Option<Box<JsObj>>;

pub struct JsObj {
    proto: JsProto,
    dict: HashMap<JsType, JsType>,
}

impl JsT for JsObj {}

impl JsObj {
    pub fn new() -> JsObj {
        JsObj {
            proto: None,
            dict: HashMap::new(),
        }
    }

    pub fn with_pairs(pairs: Vec<(JsType, JsType)>) -> JsObj {
        let mut dict = HashMap::new();
        for (k, v) in pairs {
            dict.insert(k, v);
        }
        JsObj {
            proto: None,
            dict,
        }
    }
}
