async function loadToken() {
  const { execSync } = require('child_process');
  try {
    const token = execSync('npm config get //registry.npmjs.org/:_authToken', { encoding: 'utf8' }).trim();
    if (!token) {
      console.warn('Warning: No npm token found. Storybook dependencies might fail to install if private.');
    }
  } catch (error) {
    console.warn('Warning: Could not retrieve npm token.');
  }
}

function cleanDebugLog(folder: string) {
  fs
    .readdirSync(folder)
    .filter(name => name.startsWith('npm-debug.log'))
    .map(name => fsPath.join(folder, name))
    .forEach(path => fs.removeSync(path));
}
