#[macro_use(crate_version, crate_authors)]
extern crate clap;

use clap::{App, Arg};
use std::fs::File;
use std::io::{self, BufRead, BufReader, Write, BufWriter};

fn main() {
    let matches = App::new("aux2bib")
        .version(crate_version!())
        .author(crate_authors!(",\n"))
        .about("gets BibTeX keys from Inspire")
        .arg(Arg::with_name("INPUT")
            .help("Sets the input file to use")
            .index(1))
        .arg(Arg::with_name("OUTPUT")
            .help("Sets the output file to use")
            .index(2))
        .get_matches();

    let input_file = matches.value_of("INPUT").unwrap_or("aux");
    let output_file = matches.value_of("OUTPUT").unwrap_or("bib");

    let file = match File::open(input_file) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error opening input file '{}': {}", input_file, e);
            std::process::exit(1);
        }
    };

    let reader = BufReader::new(file);
    let mut keys = Vec::new();

    for line in reader.lines() {
        match line {
            Ok(l) => {
                if l.starts_with("\\bibcite{") {
                    if let Some(key) = l.strip_prefix("\\bibcite{") {
                        if let Some(end) = key.find('}') {
                            let key = &key[..end];
                            if !keys.contains(&key) {
                                keys.push(key.to_string());
                            }
                        }
                    }
                }
            }
            Err(e) => {
                eprintln!("Error reading line: {}", e);
            }
        }
    }

    let out_file = match File::create(output_file) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error creating output file '{}': {}", output_file, e);
            std::process::exit(1);
        }
    };

    let mut writer = BufWriter::new(out_file);
    for key in &keys {
        writeln!(writer, "@misc{{{key},", key = key).unwrap();
        writeln!(writer, "    note = \"Key: {}\"", key).unwrap();
        writeln!(writer, "}}").unwrap();
    }
}
