        it('should clone an IdaiFieldObject with all of its properties',
            function(){

                var initialObject = {
                    "identifier": "ob1",
                    "title": "Title",
                    "synced": 0,
                    "valid": true,
                    "type": "Object"
                };
                var clonedObject = ModelUtils.clone(initialObject);

                //clonedObject.identifier = "obNew"; // make test fail
                expect(clonedObject).toEqual(initialObject);
            }
        );

        it('should clone an object and modifications to the clone should not affect the original',
            function(){

                var initialObject = {
                    "identifier": "ob1",
                    "title": "Title",
                    "synced": 0,
                    "valid": true,
                    "type": "Object"
                };
                var clonedObject = ModelUtils.clone(initialObject);

                clonedObject.identifier = "obNew";
                expect(clonedObject.identifier).toBe("obNew");
                expect(initialObject.identifier).toBe("ob1");
            }
        );

        it('should filter unwanted object properties',
            function(){

                var initialObject = {
                    "identifier": "ob1",
                    "title": "Title",
                    "synced": 0,
                    "valid": true,
                    "type": "Object",
                    "unwantedProp": "should be removed"
                };
                var filteredObject = ModelUtils.filterUnwantedProperties(initialObject, ["unwantedProp"]);

                expect(filteredObject).not.toHaveProperty("unwantedProp");
                expect(filteredObject.identifier).toBe("ob1");
                expect(filteredObject.title).toBe("Title");
            }
        );

        it('should filter multiple unwanted object properties',
            function(){

                var initialObject = {
                    "identifier": "ob1",
                    "title": "Title",
                    "synced": 0,
                    "valid": true,
                    "type": "Object",
                    "unwantedProp1": "should be removed",
                    "unwantedProp2": "should also be removed"
                };
                var filteredObject = ModelUtils.filterUnwantedProperties(initialObject, ["unwantedProp1", "unwantedProp2"]);

