                expect(filteredObject).not.toHaveProperty("unwantedProp2");
                expect(filteredObject.identifier).toBe("ob1");
                expect(filteredObject.title).toBe("Title");
            }
        );

        it('should return the original object if no properties are filtered',
            function(){

                var initialObject = {
                    "identifier": "ob1",
                    "title": "Title"
                };
