```rust
pub fn find_saddle_points(input: &[Vec<u64>]) -> Vec<(usize, usize)> {
    if input.is_empty() || input[0].is_empty() {
        return Vec::new();
    }

    let rows = input.len();
    let cols = input[0].len();

    // Precompute the maximum value for each row
    let row_maxs: Vec<u64> = input
        .iter()
        .map(|row| row.iter().copied().max().unwrap_or(0))
        .collect();

    // Precompute the minimum value for each column
    let col_mins: Vec<u64> = (0..cols)
        .map(|col| input.iter().map(|row| row[col]).min().unwrap_or(0))
        .collect();

    // Find all saddle points
    let mut saddle_points = Vec::new();
    for row in 0..rows {
        for col in 0..cols {
            let value = input[row][col];
            if value == row_maxs[row] && value == col_mins[col] {
                saddle_points.push((row, col));
            }
        }
    }

    saddle_points
}
