```typescript

/**
 * @class EventEmitter
 * @description Very basic events support with listeners.
 */
export class EventEmitter {
  private listeners : { [s:string]: Function[] } = {};

  constructor(names: string[]) {
    names.forEach((n:string) => this.listeners[n] = []);
  }

  /**
   * Start listening to an event.
   * @method EventEmitter#on
   * @param  {string}   name [event name]
   * @param  {Function} f [callback function]
   */
  on(name: string, f: Function) {
    this.listeners[name].push(f);
  }

  emit(name: string, thisArg: any, ...args) {
    this.listeners[name].forEach((l) => l.apply(thisArg, args));
  }

  emitAsync(name: string, thisArg: any, ...args) {
    setTimeout(() => {
      this.listeners[name].forEach((l) => l.apply(thisArg, args));
    }, 0);
  }

  /**
   * Forward events from another EventEmitter to this one.
   * @method EventEmitter#forward
   * @param  {EventEmitter} source [the source EventEmitter]
   * @param  {string|string[]} events [event name(s) to forward]
   */
  forward(source: EventEmitter, events: string | string[]) {
    const eventList = Array.isArray(events) ? events : [events];
    eventList.forEach((eventName) => {
      source.on(eventName, (...args: any[]) => {
        this.emit(eventName, this, ...args);
      });
    });
  }
}

