```rust
use std::io;
use std::io::Write; // need it to flush stdout
use std::process::Command;

static PROMPT: &'static str = "$ ";

fn execute(cmd: &str) {
    if cmd.is_empty() {
        return;
    }

    let parts: Vec<&str> = cmd.split_whitespace().collect();
    if parts.is_empty() {
        return;
    }

    let program = parts[0];
    let args = &parts[1..];

    println!("Executing: {} {}", program, args.join(" "));

    let status = Command::new(program)
        .args(args)
        .status();

    match status {
        Ok(status) => {
            if !status.success() {
                eprintln!("Command exited with status: {}", status);
            }
        }
        Err(why) => {
            eprintln!("error: {}", why);
        }
    }
}

fn main() {

    // we allocate a String for the user input
    let mut input: String = String::new();

    loop {

        print!("{}", PROMPT);
        if let Err(why) = io::stdout().flush() {
            println!("error: {}", why);
            continue;
        }

        // input probably has stuff in it from the last command, so clear
        // it out
        input.clear();

        // read input into our String. if there was an error, print the
        // error message and continue
        if let Err(why) = io::stdin().read_line(&mut input){
            println!("error: {}", why);
            continue;
        }

        // trim the newline off and save it back
        input = input.trim().to_string();

        if input == "exit" {
            println!("Exiting!");
            break;
        }

        execute(&input);
    }

}
