```typescript
import { Injectable } from "@angular/core";
import { CanActivate, Router } from "@angular/router";
import { ActivatedRouteSnapshot } from "@angular/router";
import { RouterStateSnapshot } from "@angular/router";
import log from "loglevel";

/**
 *
 */
@Injectable()
export class AppNameGuard implements CanActivate {
  private backupAppName: string | null = null;

  constructor(private router: Router) {}

  setBackupAppName(appName: string): void {
    this.backupAppName = appName;
  }

  canActivate(
    route: ActivatedRouteSnapshot,
    state: RouterStateSnapshot
  ): boolean {
    const appName = route.url[0].path;
    if (appName === "chipster" || appName === "mylly") {
      return true;
    } else {
      log.warn("invalid appName", appName, "redirecting to chipster home");
      const redirectPath = this.backupAppName ? `/${this.backupAppName}/home` : "/chipster/home";
      this.router.navigateByUrl(redirectPath);
      return false;
    }
  }
}
