```rust
//! Hints (suggestions at the right of the prompt as you type).

use crate::history::Direction;
use crate::Context;

/// Hints provider
pub trait Hinter {
    /// Takes the currently edited `line` with the cursor `pos`ition and
    /// returns the string that should be displayed or `None`
    /// if no hint is available for the text the user currently typed.
    // TODO Validate: called while editing line but not while moving cursor.
    fn hint(&self, line: &str, pos: usize, ctx: &Context) -> Option<String>;
}

impl Hinter for () {
    fn hint(&self, _line: &str, _pos: usize, _ctx: &Context) -> Option<String> {
        None
    }
}

pub struct HistoryHinter {}

impl Hinter for HistoryHinter {
    fn hint(&self, line: &str, pos: usize, ctx: &Context) -> Option<String> {
        let start = if ctx.history_index() == ctx.history().len() {
            ctx.history_index() - 1
        } else {
            ctx.history_index()
        };

        // Fix bug: if start is 0, we might still want to search, but if history is empty or start is invalid, handle gracefully.
        // The original bug was likely that when history_index is 0, the logic might fail or behave unexpectedly.
        // However, the main issue described is "when ctx.history_index() is 0".
        // If history_index is 0, start becomes 0 (unless len is 0, then start becomes -1 which is invalid).
        // Let's ensure we don't pass an invalid index.
        if start >= ctx.history().len() {
            return None;
        }

        if let Some(history_index) =
            ctx.history
                .starts_with(&line[..pos], start, Direction::Reverse)
        {
            let entry = ctx.history.get(history_index);
            if let Some(entry) = entry {
                if entry == line || entry == &line[..pos] {
                    return None;
                }
            }
            return entry.map(|s| s[pos..].to_owned());
        }
        None
    }
}
