function createRegExp(highlight: string[]) : RegExp {
  let regex: string;
  highlight.forEach((h: string) => {
    // Allow @name and name: formats by stripping leading @ or trailing :
    let cleanH = h;
    if (cleanH.startsWith('@')) {
      cleanH = cleanH.substring(1);
    }
    if (cleanH.endsWith(':')) {
      cleanH = cleanH.substring(0, cleanH.length - 1);
    }

    if (!regex) {
      regex = '\\b' + cleanH + '\\b';
    } else {
      regex += '|\\b' + cleanH + '\\b';
    }
  });
  return new RegExp(regex, 'g');
}

export default {
  fromText,
  createRegExp
}
