#[repr(packed)]
#[derive(Clone, Copy, Debug, Default)]
pub struct SSDT {
    pub header: SDTHeader,
    pub data: &'static [u8]
}

impl SSDT {
    pub fn new(header: *const SDTHeader) -> Option<Self> {
        let header_ref = unsafe { &*header };
        if header_ref.valid("SSDT") {
            Some(SSDT {
                header: *header_ref,
                data: header_ref.data(),
            })
        } else {
            None
        }
    }
}
