fn is_prime(num: u64) -> bool {
    if num < 2 {
        return false;
    }
    if num < 4 {
        return true;
    }
    if num % 2 == 0 || num % 3 == 0 {
        return false;
    }
    let mut i = 5;
    while i * i <= num {
        if num % i == 0 || num % (i + 2) == 0 {
            return false;
        }
        i += 6;
    }
    true
}

fn factorize_prime(num: u64) {
    let mut n = num;
    let mut i = 2;
    while i * i <= n {
        while n % i == 0 {
            println!("{}", i);
            n /= i;
        }
        i += 1;
    }
    if n > 1 {
        println!("{}", n);
    }
}

#[test]
fn is_prime_test() {
    assert!(!is_prime(4), "{} {} {}", is_prime(4), false, 4);
}

#[test]
fn is_prime_test2() {
    assert!(is_prime(5), "{} {} {}", is_prime(5), true, 5);
}

fn main() {
    factorize_prime(2332377667);
}
