use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::Path;

use clap::{App, Arg, ArgMatches};

fn main() {
    let matches = App::new("utility")
        .version("1.0")
        .author("Your Name <you@example.com>")
        .about("Performs some utility operations")
        .arg(
            Arg::with_name("input")
                .help("Specifies the input file to use")
                .required(true)
                .index(1),
        )
        .arg(
            Arg::with_name("output")
                .help("Specifies the output file to use")
                .short("o")
                .long("output")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("verbose")
                .help("Turns on verbose mode")
                .short("v")
                .long("verbose")
                .multiple(true),
        )
        .get_matches();

    let input = matches.value_of("input").unwrap();
    let output = matches.value_of("output");
    let verbose = matches.is_present("verbose");

    if verbose {
        println!("Input file: {}", input);
        if let Some(output) = output {
            println!("Output file: {}", output);
        }
    }

    let input_path = Path::new(input);
    if !input_path.exists() {
        eprintln!("Input file does not exist: {}", input);
        std::process::exit(1);
    }

    let content = fs::read_to_string(input_path).expect("Failed to read input file");

    if let Some(output) = output {
        let output_path = Path::new(output);
        fs::write(output_path, &content).expect("Failed to write output file");
        if verbose {
            println!("Output written to: {}", output);
        }
    } else {
        println!("{}", content);
    }
}
