import { MarkdownPlugin } from '../../plugin';

export function relativeUrl(absolute: string) {
  const urlPrefix: RegExp = /^(http|ftp)s?:\/\//;
  if (!MarkdownPlugin.location || urlPrefix.test(absolute)) {
    return absolute;
  } else {
