```rust
extern crate rand;

use rand::thread_rng;
use rand::distributions::Distribution;
use individual::Individual;

mod individual;

fn tournament_selection(population: &[Individual], rng: &mut thread_rng::ThreadRng, tournament_size: usize) -> Individual {
    let mut best = None;
    for _ in 0..tournament_size {
        let idx = rng.gen_range(0, population.len());
        let candidate = &population[idx];
        match best {
            None => best = Some(candidate),
            Some(b) => {
                if candidate.fitness < b.fitness {
                    best = Some(candidate);
                }
            }
        }
    }
    best.unwrap().clone()
}

fn main() {
    let mut rng = thread_rng();
    let range = rand::distributions::Uniform::new(-512.03_f64, 511.97); // range for Schwefel problem

    // initialize population
    let mut population: Vec<_> = (0..128).map(|_| {
        Individual::new(&range, &mut rng)
    }).collect();

    for i in 0..10000 {
        // generate mutated offspring
        let offspring: Vec<Individual> = population.iter().map(|x| {
            x.mutate(&range, &mut rng)
        }).collect();

        // combine parents and offspring
        let mut combined: Vec<Individual> = population.clone();
        combined.extend(offspring);

        // tournament selection to form new population
        population = (0..128).map(|_| {
            tournament_selection(&combined, &mut rng, 3)
        }).collect();

        let best = population.iter().min().unwrap();
        if i % 100 == 0 {
            println!("{}th fitness: {}", i, best.fitness);
        }

        if best.fitness < 1000_f64 {
            println!("Solution: {:?}", best.solution);
            return;
        }
    }
    println!("Failed to converge.");
}
```

