fn double_first(vec: Vec<&str>) -> Result<i32, String> {
    // Returns an error if the input vector is empty:
    let first = vec.first().ok_or_else(|| String::from("empty vector"))?;

    // Returns an error if the element doesn't parse to a number:
    let parsed = first.parse::<i32>().map_err(|e| e.to_string())?;
    Ok(2 * parsed)
}

