      if (!data) return path
      return path.replace(replacePattern, data)
    })
  })

  compiler.hooks.emit.tap('GitRevisionWebpackPlugin', compilation => {
    // Fix: Use compilation.emitAsset instead of directly assigning to compilation.assets
    // to avoid the "No more changes should happen to Compilation.assets after sealing" error.
    compilation.emitAsset(asset, {
      source: function() {
        return data
      },
      size: function() {
        return data ? data.length : 0
      },
      buffer: function() {
        return Buffer.from(data)
      },
      map: function() {
        return {}
      },
      sourceAndMap: function() {
        return { source: data, map: {} }
      },
