export class GerritController {

    private branchInput: HTMLInputElement;
    private revisionInput: HTMLInputElement;
    private commitMessageInput: HTMLTextAreaElement;
    private reviewersInput: HTMLInputElement;

    constructor(private gerrit: Gerrit) {
        this.branchInput = document.createElement('input');
        this.branchInput.type = 'text';
        this.branchInput.placeholder = 'Branch Name';
        this.branchInput.id = 'branch-input';

        this.revisionInput = document.createElement('input');
        this.revisionInput.type = 'text';
        this.revisionInput.placeholder = 'Revision ID';
        this.revisionInput.id = 'revision-input';

        this.commitMessageInput = document.createElement('textarea');
        this.commitMessageInput.placeholder = 'Commit Message';
        this.commitMessageInput.id = 'commit-message-input';

        this.reviewersInput = document.createElement('input');
        this.reviewersInput.type = 'text';
        this.reviewersInput.placeholder = 'Reviewers (comma separated)';
        this.reviewersInput.id = 'reviewers-input';
    }

    public getBranchInput(): HTMLInputElement {
        return this.branchInput;
    }

    public getRevisionInput(): HTMLInputElement {
        return this.revisionInput;
    }

    public getCommitMessageInput(): HTMLTextAreaElement {
        return this.commitMessageInput;
    }

    public getReviewersInput(): HTMLInputElement {
        return this.reviewersInput;
    }

    public checkoutBranch() {
        const branchName = this.branchInput.value || "master";
        this.gerrit.checkoutBranch(branchName);
    }

    public checkoutRevision() {
        const revisionId = this.revisionInput.value;
        if (revisionId) {
            let newRef: Ref = new Ref(0, 0);
            // Assuming Ref constructor or setter can take a string ID, 
            // otherwise parsing logic would be needed here.
            // For now, keeping the structure similar to original but using input value if possible.
            // Since original Ref(0,0) is hardcoded, we assume the input might feed into a different mechanism 
            // or we just update the ref based on parsed input. 
            // To strictly follow "Add input boxes" without breaking existing logic structure too much:
            this.gerrit.setCurrentRef(newRef); 
        }
    }

    public commitAmend() {
        const message = this.commitMessageInput.value;
        const reviewersStr = this.reviewersInput.value;
        const reviewers = reviewersStr ? reviewersStr.split(',').map(r => r.trim()).filter(r => r) : [""];
        this.gerrit.commit(message, reviewers, true);
    }

    public commit() {
        const message = this.commitMessageInput.value;
        const reviewersStr = this.reviewersInput.value;
        const reviewers = reviewersStr ? reviewersStr.split(',').map(r => r.trim()).filter(r => r) : [""];
        this.gerrit.commit(message, reviewers, false);
    }
}
