//! Conversion traits for handling lossy type conversions.
//!
//! This module provides `FromLossy` and `IntoLossy` traits to facilitate
//! conversions between types where data might be lost or truncated.
//! These traits are particularly useful when converting between fixed-size
//! integers of different widths or other types where precision may be reduced.

pub trait FromLossy<T>: Sized {
    /// Converts a value of type `T` into `Self`, potentially losing data.
    ///
    /// # Arguments
    ///
    /// * `value` - The value to convert from.
    ///
    /// # Returns
    ///
    /// The converted value of type `Self`.
    fn from_lossy(_: T) -> Self;
}

pub trait IntoLossy<T>: Sized {
    /// Converts `self` into a value of type `T`, potentially losing data.
    ///
    /// # Returns
    ///
    /// The converted value of type `T`.
    fn into_lossy(self) -> T;
}

impl<T, U> IntoLossy<U> for T
where
    U: FromLossy<T>,
{
    /// Converts `self` into a value of type `U` using the `FromLossy` implementation.
    ///
    /// This is a blanket implementation that allows any type `T` to be converted
    /// into type `U` if `U` implements `FromLossy<T>`.
    ///
    /// # Returns
    ///
    /// The converted value of type `U`.
    fn into_lossy(self) -> U {
        U::from_lossy(self)
    }
}
