    super();
  }

  ngOnInit() {
    if (this.cell.getColumn().editor && this.cell.getColumn().editor.type === 'completer') {
      const config = this.cell.getColumn().getConfig().completer;

      // If a custom dataService is provided via input, use it
      if (this.dataService) {
        // Ensure descriptionField is set if provided in config
        if (config.descriptionField) {
          this.dataService.descriptionField(config.descriptionField);
        }
      } else {
        // Fallback to local data service if none provided
        config.dataService = this.completerService.local(config.data, config.searchFields, config.titleField);
        if (config.descriptionField) {
          config.dataService.descriptionField(config.descriptionField);
        }
        this.dataService = config.dataService;
      }
    }
  }

