use anyhow::Result;
use erased_serde::Serialize;
use std::any::Any;
use std::fs;
use std::path::PathBuf;
use structopt::StructOpt;

use opentitanlib::app::command::CommandDispatch;
use opentitanlib::app::TransportWrapper;
use opentitanlib::util::usr_access::{usr_access_set, usr_access_timestamp};

/// Update the USR_ACCESS value of an FPGA bitstream with the current timestamp.
#[derive(Debug, StructOpt)]
pub struct UpdateUsrAccess {
    #[structopt(name = "INPUT_FILE")]
    input: PathBuf,

    #[structopt(name = "OUTPUT_FILE")]
    output: PathBuf,

    #[structopt(long = "timestamp", short = "t", help = "Override the timestamp with a specific value (hex string or decimal)")]
    timestamp: Option<String>,
}

impl CommandDispatch for UpdateUsrAccess {
    fn run(
        &self,
        _context: &dyn Any,
        _transport: &TransportWrapper,
    ) -> Result<Option<Box<dyn Serialize>>> {
        let mut bs = fs::read(&self.input)?;

        let timestamp_value = if let Some(ref ts_str) = self.timestamp {
            // Try parsing as hex first (with or without 0x prefix)
            let cleaned = ts_str.trim_start_matches("0x").trim_start_matches("0X");
            u32::from_str_radix(cleaned, 16)
                .or_else(|_| ts_str.parse::<u32>())
                .map_err(|e| anyhow::anyhow!("Invalid timestamp value '{}': {}", ts_str, e))?
        } else {
            usr_access_timestamp()
        };

        usr_access_set(&mut bs, timestamp_value)?;
        fs::write(&self.output, bs)?;
        Ok(None)
    }
}
