//! Scheduling primitives for Uni.rs.

use core::cell::UnsafeCell;
use core::future::Future;
use core::pin::Pin;
use core::task::{Context, Poll, Waker};

/// A handle to a thread.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Thread {
    id: usize,
}

/// A future that represents a thread.
pub struct ThreadFuture {
    inner: UnsafeCell<ThreadInner>,
}

struct ThreadInner {
    waker: Option<Waker>,
    state: ThreadState,
}

enum ThreadState {
    Ready,
    Running,
    Finished,
}

impl ThreadFuture {
    pub fn new() -> Self {
        ThreadFuture {
            inner: UnsafeCell::new(ThreadInner {
                waker: None,
                state: ThreadState::Ready,
            }),
        }
    }
}

impl Future for ThreadFuture {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let inner = unsafe { &mut *self.get_mut().inner.get() };
        match inner.state {
            ThreadState::Ready => {
                inner.waker = Some(cx.waker().clone());
                inner.state = ThreadState::Running;
                Poll::Pending
            }
            ThreadState::Running => Poll::Pending,
            ThreadState::Finished => Poll::Ready(()),
        }
    }
}
