/**
 * CapabilityCalculator
 */

import {
	ClientCapabilities,
	ServerCapabilities,
	TextDocumentSyncKind,
} from 'vscode-languageserver';

export class CapabilityCalculator {
	public clientCapabilities: ClientCapabilities;
	public capabilities: ServerCapabilities;

	constructor(clientCapabilities: ClientCapabilities) {
		this.clientCapabilities = clientCapabilities;
		this.calculateCapabilities();
	}

	private calculateCapabilities(): void {
		this.capabilities = {
			// Perform incremental syncs
			// Incremental sync is disabled for now due to not being able to get the
			// old text
			// textDocumentSync: TextDocumentSyncKind.Incremental,
			textDocumentSync: TextDocumentSyncKind.Full,
			documentFormattingProvider: true,
			documentRangeFormattingProvider: true,
			documentHighlightProvider: true,
			documentSymbolProvider: true,
			foldingRangeProvider: true,
		};

		if (this.clientCapabilities.workspace && this.clientCapabilities.workspace.workspaceFolders) {
			this.capabilities.workspace = {
				workspaceFolders: {
					supported: true,
					changeNotifications: true,
				},
			};
		}

		if (this.clientCapabilities.workspace && this.clientCapabilities.workspace.configuration) {
			this.capabilities.workspace = {
				...this.capabilities.workspace,
				configuration: true,
			};
		}
	}

	public get supportsWorkspaceFolders(): boolean {
		return !!this.capabilities.workspace?.workspaceFolders?.supported;
	}

	public get supportsConfiguration(): boolean {
		return !!this.capabilities.workspace?.configuration;
	}
}
