//! An example of using perlin noise

extern crate noise;

use noise::perlin::*;

static WIDTH: usize = 100;
static HEIGHT: usize = 100;

static GRADIENT: [&'static str; 6] = [" ", "░", "▒", "▓", "█", "█"];

fn main() {
    let ctx = PerlinContext::new::<f32>();

    for y in 0..HEIGHT {
        for x in 0..WIDTH {
            let val = [x as f32 * 0.1f32,
                       y as f32 * 0.1f32].perlin(&ctx) * 0.5f32 + 0.5f32;
            let index = (val / 0.2f32) as usize;
            print!("{}", GRADIENT[index]);
        }
        println!("");
    }
}
