pub mod bitread;
pub mod byteread;
pub mod bytewrite;

#[macro_export]
macro_rules! tagl {
    ($bits:expr, $val:expr) => {
        {
            let mut val = $val;
            let mut bits = $bits;
            let mut result = 0u64;
            let mut shift = 0;
            while bits > 0 {
                let take = if bits > 64 { 64 } else { bits };
                result |= (val & ((1u64 << take) - 1)) << shift;
                val >>= take;
                shift += take;
                bits -= take;
            }
            result
        }
    };
}

#[macro_export]
macro_rules! tagb {
    ($bits:expr, $val:expr) => {
        {
            let mut val = $val;
            let mut bits = $bits;
            let mut result = 0u64;
            let mut shift = 0;
            while bits > 0 {
                let take = if bits > 64 { 64 } else { bits };
                result |= ((val >> (64 - take)) & ((1u64 << take) - 1)) << shift;
                val <<= take;
                shift += take;
                bits -= take;
            }
            result
        }
    };
}
