#[test]
#[cfg(feature = "vcan_tests")]
fn test_error_mask() {
    let cs = CANSocket::open("vcan1").unwrap();

    // Initially, error mask should be 0 (no errors masked)
    let initial_mask = cs.get_error_mask().unwrap();
    assert_eq!(initial_mask, 0);

    // Set error mask to some value
    cs.set_error_mask(0xFF).unwrap();
    let mask_after_set = cs.get_error_mask().unwrap();
    assert_eq!(mask_after_set, 0xFF);

    // Clear error mask
    cs.set_error_mask(0).unwrap();
    let mask_after_clear = cs.get_error_mask().unwrap();
    assert_eq!(mask_after_clear, 0);
}
