import { Component } from 'react'

import { TodoModel } from './TodoModel'
import { TodoList } from './TodoList'

interface Props {
  deleteTodo: (todo: TodoModel) => void
  todos: Array<TodoModel>
  toggleAll: (completed: boolean) => void
}

