use std::fmt::Debug;
use std::ops::{Add, Sub, Mul, Div};

pub trait GaugeValue: Debug + Clone + PartialEq + Add<Output = Self> + Sub<Output = Self> + Mul<f64, Output = Self> + Div<f64, Output = Self> + Default {}

impl<T> GaugeValue for T where T: Debug + Clone + PartialEq + Add<Output = Self> + Sub<Output = Self> + Mul<f64, Output = Self> + Div<f64, Output = Self> + Default {}

pub struct Gauge<T: GaugeValue> {
    pub value: T
}

impl<T: GaugeValue> Gauge<T> {
    pub fn new() -> Self {
        Gauge { value: T::default() }
    }

    pub fn update(&mut self, value: T) {
        self.value = value
    }

    pub fn snapshot(self) -> Gauge<T> {
        Gauge { value: self.value }
    }
}

