    let forks: Vec<Arc<Mutex<()>>> = (0..NUM_PHILOSOPHERS)
        .map(|_| Arc::new(Mutex::new(())))
        .collect();

    let mut handles = vec![];

    for i in 0..NUM_PHILOSOPHERS {
        let left = i;
        let right = (i + 1) % NUM_PHILOSOPHERS;
        let forks = forks.clone();

        let handle = thread::spawn(move || {
            let mut rng = fastrand::Rng::new();
            loop {
                // Think
                println!("Philosopher {} is thinking", i);
                thread::sleep(Duration::from_millis(rng.u128(10..100)));

                // Pick up left fork
                let left_fork = &forks[left];
                let left_guard = left_fork.lock().unwrap();

                // Pick up right fork
                let right_fork = &forks[right];
                let right_guard = right_fork.lock().unwrap();

                // Eat
                println!("Philosopher {} is eating", i);
                thread::sleep(Duration::from_millis(rng.u128(10..100)));

                // Drop forks (guards go out of scope)
                drop(right_guard);
                drop(left_guard);
            }
        });

        handles.push(handle);
    }

    // Note: In a real application, you might want to handle thread joining or use a shutdown mechanism.
    // For this example, we let the threads run indefinitely.
    for handle in handles {
        handle.join().unwrap();
    }
}
