extern crate tempfile;
use std::io::{Read, Seek, SeekFrom, Write};
use std::fs;

#[test]
fn test_basic() {
    let mut tmpfile = tempfile::tempfile().unwrap();
    write!(tmpfile, "abcde").unwrap();
    tmpfile.seek(SeekFrom::Start(0)).unwrap();
    let mut buf = String::new();
    tmpfile.read_to_string(&mut buf).unwrap();
    assert_eq!("abcde", buf);
}

#[test]
fn test_cleanup() {
    let tmpdir = tempfile::tempdir().unwrap();
    {
        let mut tmpfile = tempfile::tempfile_in(&tmpdir).unwrap();
        write!(tmpfile, "abcde").unwrap();
    }
    let num_files = fs::read_dir(&tmpdir).unwrap().count();
    assert!(num_files == 0);
}

#[test]
fn test_pathological_cleaner() {
    // Emulate a pathological temporary file cleaner that deletes files
    // while they are still open. This test ensures that the tempfile
    // library handles such scenarios gracefully (e.g., by keeping the
    // file descriptor valid even if the file is unlinked).
    let tmpdir = tempfile::tempdir().unwrap();
    let mut tmpfile = tempfile::tempfile_in(&tmpdir).unwrap();

    // Write some data
    write!(tmpfile, "abcde").unwrap();

    // Seek back to the beginning
    tmpfile.seek(SeekFrom::Start(0)).unwrap();

    // Read the data to ensure it's still accessible
    let mut buf = String::new();
    tmpfile.read_to_string(&mut buf).unwrap();
    assert_eq!("abcde", buf);

    // Now, manually delete the file from the filesystem to simulate
    // a pathological cleaner. The file should still be readable/writable
    // via the file descriptor.
    let path = tmpfile.path().to_path_buf();
    fs::remove_file(&path).unwrap();

    // Verify the file is gone from the directory
    let num_files = fs::read_dir(&tmpdir).unwrap().count();
    assert_eq!(num_files, 0);

    // But the file descriptor should still work
    write!(tmpfile, "fghij").unwrap();
    tmpfile.seek(SeekFrom::Start(0)).unwrap();
    let mut buf = String::new();
    tmpfile.read_to_string(&mut buf).unwrap();
    assert_eq!("fghij", buf);
}
