```typescript
import { Injectable } from '@angular/core';
import { Http, Headers } from '@angular/http';
import { environment } from '../index';

@Injectable()
export class HttpService {

  protected headers: Headers = new Headers();
  private cache: Map<string, any> = new Map();

  constructor(private http: Http) {
    this.headers.append('Content-Type', 'application/json');
    this.headers.append('Accept', 'application/json');
  }

  get(url: string) {
    const fullUrl = environment.endpoint + url;

    // Check cache first
    if (this.cache.has(fullUrl)) {
      return this.cache.get(fullUrl);
    }

    const observable = this.http.get(fullUrl, {headers: this.headers, withCredentials: true}).map(res => res.json());

    // Cache the observable
    this.cache.set(fullUrl, observable);

    return observable;
  }

  post(url: string, object: any) {
    // Invalidate cache on POST requests to ensure fresh data
    this.cache.clear();

    return this.http.post(environment.endpoint + url, JSON.stringify(object), {headers: this.headers, withCredentials: true}).map(res => res.json());
  }

}
