```typescript
import { MongoClient, Db, Collection } from "mongodb";

interface Db extends Db {
    users: Collection;
}

let dbInstance: Db | null = null;

export const initialize = async () => {
    if (!process.env.DB_CONNECTION_STRING) {
        console.error("No connection string found.");
        return;
    }

    try {
        const client = new MongoClient(process.env.DB_CONNECTION_STRING);
        await client.connect();
        dbInstance = client.db();

        // Ensure the users collection exists
        const collections = await dbInstance.listCollections().toArray();
        const collectionNames = collections.map(c => c.name);
        if (!collectionNames.includes("users")) {
            await dbInstance.createCollection("users");
        }
    } catch (err) {
        console.error("Failed to connect to MongoDB:", err);
    }
};

export const upsertUser = async (patreonId: string, accessKey: string, refreshKey: string, accountStatus: string, res: any) => {
    if (!process.env.DB_CONNECTION_STRING) {
        console.error("No connection string found.");
        res.status(500).json({ error: "No connection string found." });
        return;
    }

    if (!dbInstance) {
        console.error("Database not initialized.");
        res.status(500).json({ error: "Database not initialized." });
        return;
    }

    try {
        const usersCollection = dbInstance.collection("users");
        const result = await usersCollection.updateOne(
            { patreonId },
            {
                $set: {
                    patreonId,
                    accessKey,
                    refreshKey,
                    accountStatus
                }
            },
            { upsert: true }
        );
        res.json(result);
    } catch (err) {
        console.error("Error upserting user:", err);
        res.status(500).json({ error: err });
    }
};
