      primary: true,
      external: true,
      icon: 'add',
      label: 'Add Hit',
      url: `https://www.mturk.com/mturk/previewandaccept?groupId=${groupId}`
    }
  ];

  return {
    attributeOne: requesterName,
    attributeTwo: truncate(title, 80),
    badges: generateBadges(requester),
    actions,
    exceptions: generateExceptions(groupId)
  };
};
