            nrepl.info(currentWord, ns, (info) => {
                if (!info.file) {
                    // vscode.window.showInformationMessage(`Can't find definition for ${currentWord}.`);
                    reject();
                }
                let uri = vscode.Uri.parse(info.file);
                let pos = new vscode.Position(info.line - 1, info.column)
