use cocoa::base::id;

pub struct RenderCommandEncoder(id);

impl_from_into_raw!(RenderCommandEncoder, of protocol "MTLRenderCommandEncoder");

impl RenderCommandEncoder {
    /// Sets the viewport for the render command encoder.
    pub fn set_viewport(&self, viewport: MTLViewport) {
        unsafe {
            msg_send![self.0, setViewport: viewport]
        }
    }

    /// Sets the scissor rectangle for the render command encoder.
    pub fn set_scissor_rect(&self, rect: MTLScissorRect) {
        unsafe {
            msg_send![self.0, setScissorRect: rect]
        }
    }

    /// Pushes a debug group onto the command encoder.
    pub fn push_debug_group(&self, group_name: &str) {
        unsafe {
            let ns_string = cocoa::foundation::NSString::alloc(nil).init_str(group_name);
            msg_send![self.0, pushDebugGroup: ns_string]
        }
    }

    /// Pops the most recent debug group from the command encoder.
    pub fn pop_debug_group(&self) {
        unsafe {
            msg_send![self.0, popDebugGroup]
        }
    }
}

