```typescript
import { DetailedHTMLProps, ImgHTMLAttributes, useState } from 'react';
import { c } from 'ttag';
import { SHOW_IMAGES } from '@proton/shared/lib/constants';
import { isURL } from '@proton/shared/lib/helpers/validators';
import Button from '../button/Button';
import { useMailSettings } from '../../hooks';

export interface Props extends DetailedHTMLProps<ImgHTMLAttributes<HTMLImageElement>, HTMLImageElement> {
    src: string;
    text?: string;
}

const RemoteImage = ({ src, text = c('Action').t`Load image`, ...rest }: Props) => {
    const [{ ShowImages } = { ShowImages: SHOW_IMAGES.NONE }, loading] = useMailSettings();
    const [showAnyways, setShowAnyways] = useState(!isURL(src));
    const [isLoaded, setIsLoaded] = useState(false);
    const [isError, setIsError] = useState(false);

    const handleClick = () => setShowAnyways(true);

    const handleLoad = () => {
        setIsLoaded(true);
        setIsError(false);
    };

    const handleError = () => {
        setIsError(true);
        setIsLoaded(false);
    };

    if ((!loading && ShowImages & SHOW_IMAGES.REMOTE) || showAnyways) {
        if (isError) {
            return (
                <div style={{ position: 'relative', display: 'inline-block' }}>
                    <img
                        src={src}
                        referrerPolicy="no-referrer"
                        {...rest}
                        style={{ opacity: 0.5, filter: 'grayscale(100%)' }}
                        alt={rest.alt || ''}
                    />
                    <div
                        style={{
                            position: 'absolute',
                            top: 0,
                            left: 0,
                            right: 0,
                            bottom: 0,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            backgroundColor: 'rgba(0,0,0,0.1)',
                            cursor: 'pointer',
                        }}
                        onClick={handleClick}
                        title={c('Action').t`Failed to load image. Click to retry.`}
                    >
                        <span style={{ color: 'white', fontWeight: 'bold' }}>!</span>
                    </div>
                </div>
            );
        }
        return (
            <img
                src={src}
                referrerPolicy="no-referrer"
                {...rest}
                onLoad={handleLoad}
                onError={handleError}
                style={{
                    opacity: isLoaded ? 1 : 0,
                    transition: 'opacity 0.3s ease-in-out',
                }}
                alt={rest.alt || ''}
            />
        );
    }

    return <Button onClick={handleClick}>{text}</Button>;
};

export default RemoteImage;
```

