```typescript
import { assert } from './assert';
import { deprecate } from './deprecate';

declare const self: any;
declare const global: any;

export interface OrbitGlobal {
  globals: any;
  assert: (description: string, test: boolean) => void | never;
  deprecate: (message: string, test?: boolean | (() => boolean)) => void;
  uuid: () => string;
  debug: boolean;
}

// Establish the root object, `window` (`self`) in the browser, `global`
// on the server, or `this` in some virtual machines. We use `self`
// instead of `window` for `WebWorker` support.
//
// Source: https://github.com/jashkenas/underscore/blob/master/underscore.js#L11-L17
//     Underscore.js 1.8.3
//     http://underscorejs.org
//     (c) 2009-2017 Jeremy Ashkenas, DocumentCloud and Investigative Reporters & Editors
//     Underscore may be freely distributed under the MIT license.
const globals =
  (typeof self == 'object' && self.self === self && self) ||
  (typeof global == 'object' && global) ||
  {};

function generateUUID(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  // Fallback for environments without crypto.randomUUID
  // This is a simple fallback; in production, you might want a more robust solution
  // or rely on the @orbit/utils uuid implementation if crypto is not available.
  // However, the prompt asks to use crypto.randomUUID by default.
  // If crypto.randomUUID is not available, we throw or use a fallback.
  // Given the previous import of uuid from @orbit/utils, we should probably keep a fallback
  // if crypto is not present, but the instruction is to use it by default.
  // Let's assume if crypto.randomUUID is not available, we fall back to a standard UUID v4 generator
  // or the previous implementation. For strict adherence to "Use crypto.randomUUID by default",
  // we check for it first.

  // Fallback implementation (UUID v4)
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

export const Orbit: OrbitGlobal = {
  globals,
  assert,
  debug: true,
  deprecate,
  uuid: generateUUID
};
```

