import ReactResizeDetector from 'react-resize-detector'
import Loading from './Loading'
import { useStore } from './hooks/useStore'
import Window from './Window'

export default observer(() => {
  const {
    windowStore,
    focusStore: { setContainerRef },
    settingsStore
  } = useStore()
  const scrollbarRef = useRef(null)
  const onResize = () => {
    const { height } = scrollbarRef.current.getBoundingClientRect()
    windowStore.updateHeight(height)
  }

  useEffect(() => setContainerRef(scrollbarRef))

  const resizeDetector = (
    <ReactResizeDetector
      handleHeight
      refreshMode='throttle'
      refreshOptions={{ leading: true, trailing: true }}
      refreshRate={500}
      onResize={onResize}
    />
  )
  const { initialLoading, windows, visibleColumn } = windowStore

  // Determine width: use user preference if visibleColumn > 4, otherwise default to 4 columns
  const columnCount = visibleColumn > 4 ? settingsStore.windowWidth : 4
  const width = 100 / columnCount + '%'

  if (initialLoading) {
    return (
      <div ref={scrollbarRef}>
        <Loading />
        {resizeDetector}
      </div>
    )
  }

  const list = windows.map((window) => (
    <Window key={window.id} width={width} win={window} />
  ))
  return (
    <Scrollbar scrollbarRef={scrollbarRef}>
      {list}
      {resizeDetector}
    </Scrollbar>
  )
})
