```typescript
import { getDebugFunction, setDebugFunction } from '@ember/debug';

// @ts-ignore
import EmberDevTestHelperAssert from './index';

export interface Assertion {
  reset(): void;
  inject(): void;
  assert(): void;
  restore(): void;
}

export default function setupQUnit({ runningProdBuild }: { runningProdBuild: boolean }) {
  let assertion = new EmberDevTestHelperAssert({
    runningProdBuild,
    getDebugFunction,
    setDebugFunction,
  });

  let originalModule = QUnit.module;

  QUnit.module = function(name: string, _options: any, callback?: any) {
    let options = _options || {};
    let originalSetup = options.setup || options.beforeEach || function() {};
    let originalTeardown = options.teardown || options.afterEach || function() {};

    delete options.setup;
    delete options.teardown;

    options.beforeEach = function() {
      assertion.reset();
      assertion.inject();

      return originalSetup.apply(this, arguments);
    };

    options.afterEach = function() {
      let result = originalTeardown.apply(this, arguments);

      assertion.assert();
      assertion.restore();

      return result;
    };

    // Handle nested module API: if the second argument is a function, it's a nested module
    if (typeof _options === 'function') {
      callback = _options;
      options = {};
    }

    // If a callback is provided, wrap it to ensure setup/teardown runs correctly
    if (callback) {
      let originalCallback = callback;
      callback = function() {
        return originalCallback.apply(this, arguments);
      };
    }

    return originalModule(name, options, callback);
  };
}
