Reply with the complete updated file in one code block and nothing else.

```typescript
// Top-down implementation with lists

function merge<T>(left: T[], right: T[]): T[] {
  const merged = [];

  let firstLeft = left[0];
  let firstRight = right[0];

  while (left.length && right.length) {
    if (firstLeft <= firstRight) {
      merged.push(firstLeft);
      left.shift();
      firstLeft = left[0];
    } else {
      merged.push(firstRight);
      right.shift();
      firstRight = right[0];
    }
  }

  while (left.length) {
    merged.push(left.shift());
  }
  while (right.length) {
    merged.push(right.shift());
  }

  return merged;
}

export function mergeSort<T>(arr: T[]): T[] {
  if (arr.length <= 1) {
    return arr;
  }

  let left = [];
  let right = [];
  const mid = arr.length / 2;

  for (let i = 0; i < arr.length; i++) {
    const el = arr[i];
    if (i < mid) {
      left.push(el);
    } else {
      right.push(el);
    }
  }

  left = mergeSort(left);
  right = mergeSort(right);

  return merge<T>(left, right);
}

// Demo:

let arr = [3, 7, 6, 1, 2, 9, 1];
arr = mergeSort<number>(arr);

console.log(arr);
```

```typescript
// Top-down implementation with indices

function merge<T>(arr: T[], left: number, mid: number, right: number): void {
  const leftArr = arr.slice(left, mid);
  const rightArr = arr.slice(mid, right);

  let i = 0;
  let j = 0;
  let k = left;

  while (i < leftArr.length && j < rightArr.length) {
    if (leftArr[i] <= rightArr[j]) {
      arr[k++] = leftArr[i++];
    } else {
      arr[k++] = rightArr[j++];
    }
  }

  while (i < leftArr.length) {
    arr[k++] = leftArr[i++];
  }

  while (j < rightArr.length) {
    arr[k++] = rightArr[j++];
  }
}

export function mergeSort<T>(arr: T[], left: number = 0, right: number = arr.length): void {
  if (right - left <= 1) {
    return;
  }

  const mid = Math.floor((left + right) / 2);
  mergeSort(arr, left, mid);
  mergeSort(arr, mid, right);
  merge(arr, left, mid, right);
}

// Demo:

let arr = [3, 7, 6, 1, 2, 9, 1];
mergeSort<number>(arr);

console.log(arr);
