  const languageClient = new client.LanguageClient("Reason", serverOptions, clientOptions);
  command.registerAll(context, languageClient);
  request.registerAll(context, languageClient);

  // Create a clickable status bar item for Merlin
  const merlinStatusBar = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 100);
  merlinStatusBar.text = "$(check) Merlin";
  merlinStatusBar.command = "merlin.showOutput"; // Example command, adjust as needed
  merlinStatusBar.show();
  context.subscriptions.push(merlinStatusBar);

  return languageClient.start();
}
