pub fn distance(input: &str) -> i32 {
    3
}```

```rust
pub fn distance(input: &str) -> i32 {
    let mut x = 0;
    let mut y = 0;
    let mut dir = 0; // 0: N, 1: E, 2: S, 3: W

    for instruction in input.split(',') {
        let instruction = instruction.trim();
        if instruction.is_empty() {
            continue;
        }
        let turn = instruction.chars().next().unwrap();
        let steps: i32 = instruction[1..].parse().unwrap();

        match turn {
            'L' => dir = (dir + 3) % 4,
            'R' => dir = (dir + 1) % 4,
            _ => {}
        }

        match dir {
            0 => y += steps,
            1 => x += steps,
            2 => y -= steps,
            3 => x -= steps,
            _ => {}
        }
    }

    (x.abs() + y.abs()) as i32
}
```

