```typescript
import assertDefined from '../assertDefined.js';

export default async function closeOtherTabs() {
	const [sourceTab, windows] = await Promise.all([
		browser.tabs.getCurrent(),
		browser.windows.getAll({ populate: true })
	]);
	// Identify the window that hosts the sourceTab
	let sourceWindow = assertDefined(windows.find(w => assertDefined(w.id) === sourceTab.windowId));
	// Close other windows
	for (let w of windows) {
		if (w === sourceWindow) { continue; }
		browser.windows.remove(assertDefined(w.id));
	}
	// Close other tabs, but keep the current popup tab open if it's the only one in the window
	// or if we are closing all tabs in the source window, we must ensure the popup itself isn't closed.
	// The issue "close all tabs closing the popup" usually happens when `browser.tabs.remove` is called
	// on the current tab or when the window is closed while the popup is the only tab.
	// Here we are closing tabs in the source window. We must exclude the sourceTab itself.
	let tabIds = assertDefined(sourceWindow.tabs).map(t => assertDefined(t.id)).filter(id => id !== sourceTab.id);

	// If there are no other tabs to close, we are done.
	if (tabIds.length === 0) {
		return;
	}

	browser.tabs.remove(tabIds);
}
