export const deriveStatusIconColor = ({
    syncState,
    backupState,
    lastSuccessfulSyncDate,
}: RootState): 'green' | 'red' | 'yellow' => {
    const daysSinceLastSync = moment().diff(
        moment(lastSuccessfulSyncDate),
        'days',
