```rust
mod markdown {
    use pulldown_cmark::Parser;
    use pulldown_cmark::Event;
    use pulldown_cmark::Tag;

    pub struct MarkdownParser<'a> {
        text: &'a String
    }

    impl<'a> MarkdownParser<'a> {

        pub fn new(s: &'a String) -> MarkdownParser {
            MarkdownParser {
                text: s
            }
        }

        pub fn links(&self) -> Vec<String> {
            self.extract_items(|tag| {
                match tag {
                    Tag::Link(url, text) => Some((url, text)),
                    _               => None
                }
            })
        }

        pub fn codeblocks(&self) -> Vec<String> {
            self.extract_items(|tag| {
                match tag {
                    Tag::CodeBlock(text)    => Some(text),
                    _                       => None
                }
            })
        }

        fn extract_items<F>(&self, filter: F) -> Vec<String>
        where
            F: Fn(&Tag) -> Option<String>
        {
            Parser::new(&self.text[..])
                .filter_map(|e| {
                    match e {
                        Event::Start(t) => Some(t),
                        Event::End(t)   => Some(t),
                        _               => None
                    }
                })
                .filter_map(|tag| filter(&tag))
                .collect::<Vec<String>>()
        }

    }

}
