```rust
use mio::*;
use mio::tcp::TcpListener;
use std::net::{IpAddr, Ipv4Addr, SocketAddr};

use super::eventhandler::*;

pub struct Relay {
    port: u16,
}

impl Relay {
    pub fn new(port: u16) -> Relay {
        Relay {
            port: port
        }
    }

    pub fn start(&self) {
        println!("Starting on port {}", self.port);

        let mut manager = HandlerTokenManager::new();
        let poll = Poll::new().expect("Failed to create Poll instance");
        let mut events = Events::with_capacity(1024);

        let localhost = IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1));
        let addr = SocketAddr::new(localhost, self.port);

        // Setup the server socket
        let server = TcpListener::bind(&addr).expect("Failed to bind to address");

        // Create a poll instance

        // Start listening for incoming connections
        let token = manager.register(Box::new(|ready| {
            println!("Ready! {:?}", ready);
        }));
        poll.register(&server, token, Ready::readable(),
                      PollOpt::edge()).expect("Failed to register server socket with poll");

        // Create storage for events


        loop {
            poll.poll(&mut events, None).expect("Poll failed");

            for event in &events {
                println!("event={:?}", event);
                let handler = manager.get(&event.token()).expect("Handler not found for token");
                handler.on_ready(event.readiness());
            }
        }
    }
}
