/**
 * Sanitize a proposed branch name by replacing illegal characters.
 * The regex matches control characters, whitespace, and other characters
 * that are not allowed in Git branch names, as well as sequences like
 * `..`, leading/trailing dots, `.lock` suffixes, and trailing slashes.
 */
export function sanitizedBranchName(name: string): string {
  return name.replace(/[\x00-\x20\x7F~^:?*\[\\|""<>]|@{|\.\.+|^\.|\.$|\.lock$|\/$/g, '-')
    .replace(/--+/g, '-')
    .replace(/^-/g, '')
