import axios from 'axios';
import { FORMAT_SQL_API } from 'api/urls';

export const formatSql = async (options: {
  statements: string;
  silenceErrors?: boolean;
}): Promise<string> => {
  try {
    const response = await axios.post<{
      formatted_statements: string;
      status: number;
    }>(FORMAT_SQL_API, { statements: options.statements });
    return (response.data && response.data.formatted_statements) || options.statements;
  } catch (err) {
    if (!options.silenceErrors) {
      throw err;
    }
  }
  return options.statements;
};
