use vm::VM;
use program::Program;
use std::io::{self, Write};
use std::env;
use std::path::Path;
use std::fs::File;

fn main() {
    let vm = VM::new();
    let program = Program::new();
    match env::args().nth(1) {
        None => repl(vm, program),
        Some(arg) => interpreter(arg, vm, program),
    }
