```rust
#[macro_use]
extern crate clap;
extern crate regex;
extern crate xml;

pub mod parse;
pub mod serialize;

use clap::{App, Arg};
use std::fs::File;
use std::io::{self, BufReader, Read};

fn main() {
    let args = App::new("script-extractor")
                   .version(&crate_version!())
                   .about("Parse movie scripts (pdf) to a structured format (xml)")
                   .arg(Arg::with_name("input-file")
                            .help("xml extracted using 'pdftohtml -xml script.pdf'. If not provided, reads from stdin.")
                            .index(1)
                            .required(false)
                            .validator(check_file_exists))
                   .get_matches();

    let scenes = match args.value_of("input-file") {
        Some(input_file) => {
            let file_reader = File::open(input_file).expect("Cannot open file");
            let buffered_file_reader = Box::new(BufReader::new(file_reader));
            parse::parse_script(buffered_file_reader)
        }
        None => {
            let mut buffer = Vec::new();
            io::stdin().read_to_end(&mut buffer).expect("Cannot read from stdin");
            let buffered_stdin_reader = Box::new(BufReader::new(io::Cursor::new(buffer)));
            parse::parse_script(buffered_stdin_reader)
        }
    };

    serialize::xml::format_script(&scenes, &mut std::io::stdout()).unwrap();
}

fn check_file_exists(file_name: String) -> Result<(), String> {
    if let Ok(metadata) = std::fs::metadata(&file_name) {
        if metadata.is_file() && !metadata.permissions().readonly() {
            Ok(())
        } else {
            Err(format!("Cannot read file '{}'", file_name))
        }
    } else {
        Err(format!("File '{}' not found", file_name))
    }
}
```

