```typescript
/**
 * Represents the input data to be parsed.
 * This type is intentionally broad to allow for various input formats.
 */
export type ParserInput = any;

/**
 * A function type that takes a `ParserInput` and returns a parsed value of type `T`.
 * @template T The type of the parsed result.
 */
export type ParseFn<T> = (x: ParserInput) => T;

/**
 * Represents an error that occurs during the parsing process.
 */
export class ParserError extends Error {
  /**
   * Creates a new ParserError.
   * @param expected - A description of what was expected.
   * @param found - A description of what was actually found.
   */
  constructor(
    public readonly expected: string,
    public readonly found: string
  ) {
    super(`Expected ${expected} but found ${found}`);
  }
}

/**
 * Executes a parser function on the given input.
 * @template T The type of the parsed result.
 * @param input - The input data to parse.
 * @param parser - The parser function to execute.
 * @returns The parsed result of type `T`.
 */
export function parse<T>(input: ParserInput, parser: ParseFn<T>): T {
  return parser(input);
}
