  process.exit(1);
}

export function readMultilineParamFile(path: string): string[] {
  return fs.readFileSync(path, {encoding: 'utf-8'}).split(/\r?\n/).filter(f => f.length > 0);
}

/**
 * Parses a string argument that may be surrounded by quotes, handling escaped quotes.
 * This fixes an infinite loop that occurred when Bazel passed arguments with
 * surrounded quotes.
 *
 * @param arg The argument string to parse.
 * @returns The parsed string with surrounding quotes removed and escapes handled.
 */
export function parseQuotedArgument(arg: string): string {
  if (arg.length < 2) {
    return arg;
  }

  const firstChar = arg[0];
  const lastChar = arg[arg.length - 1];

  if ((firstChar === '"' && lastChar === '"') || (firstChar === "'" && lastChar === "'")) {
    // Remove surrounding quotes
    let inner = arg.slice(1, -1);

    // Handle escaped quotes inside the string
    // Replace \" with " and \' with '
    inner = inner.replace(/\\(["'])/g, '$1');

    return inner;
  }

  return arg;
}
