import * as React from "react";

export interface DebounceProps<T extends (...args: any[]) => void> {
  children: (callback: T) => React.ReactNode;
  debounceFn: T;
  time?: number;
}

export class Debounce<T extends (...args: any[]) => void> extends React.Component<DebounceProps<T>> {
  timer: ReturnType<typeof setTimeout> | null = null;

  handleDebounce = (...args: Parameters<T>) => {
    const { debounceFn, time } = this.props;
    if (this.timer) {
      clearTimeout(this.timer);
    }
    this.timer = setTimeout(() => debounceFn(...args), time || 200);
  };

  render() {
    return this.props.children(this.handleDebounce);
  }
}

export default Debounce;
