```typescript
import { VNode, render, update } from "ivi";
import { triggerNextTick, triggerNextFrame } from "./scheduler";
import { reset } from "./reset";
import { VNodeWrapper } from "./vdom";

// Internal container used for DOM testing.
// This container is reused across tests to avoid repeated DOM manipulation.
let _container: HTMLDivElement | null = null;

/**
 * A renderer class that wraps ivi's rendering and updating logic.
 * It provides methods to render VNodes, update the DOM, and trigger
 * scheduling callbacks for testing purposes.
 */
export class DOMRenderer {
  private container: HTMLDivElement;

  /**
   * Creates a new DOMRenderer instance.
   * @param container - The HTML div element to render into.
   */
  constructor(container: HTMLDivElement) {
    this.container = container;
  }

  /**
   * Renders a VNode into the container.
   * @param vnode - The VNode to render.
   * @returns A VNodeWrapper representing the rendered node.
   */
  render(vnode: VNode<any>): VNodeWrapper {
    render(vnode, this.container);
    return new VNodeWrapper(vnode, null, {});
  }

  /**
   * Triggers an update cycle for the current VNode tree.
   */
  update(): void {
    update();
  }

  /**
   * Triggers the next tick callback, simulating asynchronous updates.
   */
  nextTick(): void {
    triggerNextTick();
  }

  /**
   * Triggers the next frame callback, simulating requestAnimationFrame.
   * @param time - Optional timestamp for the frame.
   */
  nextFrame(time?: number): void {
    triggerNextFrame(time);
  }
}

/**
 * Initializes the DOM renderer by creating or resetting the test container.
 * If the container already exists, its content is cleared.
 * Resets the internal state of ivi before returning the renderer.
 * @returns A new DOMRenderer instance.
 */
export function initDOMRenderer(): DOMRenderer {
  if (_container === null) {
    _container = document.createElement("div");
    _container.className = "ivi-dom-test-container";
    document.body.appendChild(_container);
  } else {
    _container.innerText = "";
  }

  reset();

  return new DOMRenderer(_container);
}
