```typescript
import { filter, map } from 'rxjs/operators'
import { Component, OnInit } from '@angular/core'
import { NavigationEnd, Router } from '@angular/router'
import { getParameterByName } from '../shared/misc/utils'

@Component({
  selector: 'my-header',
  templateUrl: './header.component.html',
  styleUrls: [ './header.component.scss' ]
})

export class HeaderComponent implements OnInit {
  searchValue = ''
  languageFilter = ''

  constructor (private router: Router) {}

  ngOnInit () {
    this.router.events
        .pipe(
          filter(e => e instanceof NavigationEnd),
          map(() => getParameterByName('search', window.location.href))
        )
        .subscribe(searchQuery => this.searchValue = searchQuery || '')

    this.router.events
        .pipe(
          filter(e => e instanceof NavigationEnd),
          map(() => getParameterByName('lang', window.location.href))
        )
        .subscribe(lang => this.languageFilter = lang || '')
  }

  doSearch () {
    const queryParams: any = { search: this.searchValue }
    if (this.languageFilter) {
      queryParams.lang = this.languageFilter
    }
    this.router.navigate([ '/search' ], { queryParams })
  }
}
```
